/** Original Air Slice illustrations. Side halves are clipped vertically at local x=0.
 * All coordinates are centered on the caller's already-rotated origin. The fruit
 * silhouette fits ±r; optional special halos extend to 1.08r. No DOM on import. */
export const FRUIT_ART=[
 {id:'watermelon',name:'Watermelon',color:'#4d9566',juice:'#ef6972',inside:'#f56f7b'},
 {id:'apple',name:'Apple',color:'#ed6f64',juice:'#f6a183',inside:'#fff0c4'},
 {id:'orange',name:'Orange',color:'#f5a348',juice:'#ffc468',inside:'#ffc064'},
 {id:'banana',name:'Banana',color:'#f3cf69',juice:'#f7dda0',inside:'#fff1be'},
 {id:'strawberry',name:'Strawberry',color:'#df6674',juice:'#f28794',inside:'#ffacb0'},
 {id:'pineapple',name:'Pineapple',color:'#dfac51',juice:'#ffe08e',inside:'#ffe8a5'},
 {id:'kiwi',name:'Kiwi',color:'#9d8056',juice:'#a9cb6f',inside:'#b5d77e'},
 {id:'lemon',name:'Lemon',color:'#edce5b',juice:'#fff08a',inside:'#fff1ab'},
 {id:'peach',name:'Peach',color:'#efa27e',juice:'#ffc0a0',inside:'#ffdcac'},
 {id:'coconut',name:'Coconut',color:'#997354',juice:'#f4e7ce',inside:'#fff6dd'}
];
const TAU=Math.PI*2,INK='#4b5149';
function ellipse(c,x,y,rx,ry,fill,stroke=null,width=.028){c.beginPath();c.ellipse(x,y,Math.max(.001,rx),Math.max(.001,ry),0,0,TAU);if(fill){c.fillStyle=fill;c.fill();}if(stroke){c.strokeStyle=stroke;c.lineWidth=width;c.stroke();}}
function line(c,points,color,width=.03){if(!points.length)return;c.beginPath();c.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)c.lineTo(points[i][0],points[i][1]);c.lineWidth=width;c.strokeStyle=color;c.stroke();}
function grad(c,x1,y1,x2,y2,stops){const g=c.createLinearGradient(x1,y1,x2,y2);stops.forEach(([a,b])=>g.addColorStop(a,b));return g;}
function shape(c,type){c.beginPath();if(type==='watermelon')c.ellipse(0,.04,.88,.81,-.16,0,TAU);
 else if(type==='apple'||type==='peach'){c.moveTo(0,-.52);c.bezierCurveTo(-.44,-.93,-.95,-.48,-.85,.13);c.bezierCurveTo(-.79,.66,-.45,.96,-.08,.78);c.quadraticCurveTo(0,.75,.09,.8);c.bezierCurveTo(.47,.95,.86,.57,.87,.06);c.bezierCurveTo(.89,-.54,.41,-.91,0,-.52);}
 else if(type==='orange')c.ellipse(0,.04,.85,.83,0,0,TAU);
 else if(type==='banana'){c.moveTo(-.76,-.63);c.bezierCurveTo(-.86,-.19,-.72,.57,-.17,.76);c.bezierCurveTo(.37,.99,.92,.48,.87,-.09);c.bezierCurveTo(.53,.38,.14,.44,-.18,.17);c.bezierCurveTo(-.45,-.05,-.53,-.35,-.55,-.68);c.closePath();}
 else if(type==='strawberry'){c.moveTo(0,-.52);c.bezierCurveTo(-.21,-.76,-.82,-.62,-.84,-.14);c.bezierCurveTo(-.84,.27,-.3,.82,0,.94);c.bezierCurveTo(.27,.84,.81,.31,.83,-.13);c.bezierCurveTo(.84,-.57,.3,-.78,0,-.52);}
 else if(type==='pineapple'){c.moveTo(-.49,-.35);c.bezierCurveTo(-.75,-.08,-.77,.52,-.49,.82);c.quadraticCurveTo(0,1.01,.49,.82);c.bezierCurveTo(.77,.53,.76,-.04,.49,-.35);c.quadraticCurveTo(0,-.56,-.49,-.35);}
 else if(type==='kiwi')c.ellipse(0,.03,.77,.88,.25,0,TAU);
 else if(type==='lemon'){c.moveTo(-.97,.02);c.quadraticCurveTo(-.81,-.06,-.76,-.24);c.bezierCurveTo(-.4,-.87,.44,-.8,.79,-.23);c.quadraticCurveTo(.82,-.07,.98,.01);c.quadraticCurveTo(.83,.13,.77,.29);c.bezierCurveTo(.37,.84,-.43,.83,-.78,.28);c.quadraticCurveTo(-.81,.12,-.97,.02);}
 else c.ellipse(0,.07,.81,.84,-.12,0,TAU);
 c.closePath();}
function leaf(c,x,y,size=1,rotation=0,color='#65a57a'){c.save();c.translate(x,y);c.rotate(rotation);c.scale(size,size);c.beginPath();c.moveTo(-.03,.02);c.bezierCurveTo(.02,-.32,.35,-.43,.54,-.29);c.quadraticCurveTo(.38,.07,-.03,.02);c.fillStyle=color;c.fill();c.strokeStyle='#42765d';c.lineWidth=.025;c.stroke();line(c,[[.02,-.01],[.34,-.23]],'#b8d48b',.022);c.restore();}
function seeds(c,list,color='#76514a',size=.045){c.fillStyle=color;for(const [x,y,a=0]of list){c.save();c.translate(x,y);c.rotate(a);c.beginPath();c.ellipse(0,0,size*.55,size,0,0,TAU);c.fill();c.restore();}}
function segmented(c,type){const lemon=type==='lemon';ellipse(c,0,.03,lemon?.86:.79,lemon?.62:.77,lemon?'#fff1ae':'#ffe3a0');ellipse(c,0,.03,lemon?.76:.69,lemon?.53:.67,lemon?'#f6d866':'#f7a849');c.save();c.translate(0,.03);if(lemon)c.scale(1.3,.88);for(let i=0;i<9;i++){const a=i*TAU/9;c.beginPath();c.moveTo(Math.cos(a)*.085,Math.sin(a)*.085);c.arc(0,0,.61,a+.045,a+TAU/9-.045);c.closePath();c.fillStyle=i%2?(lemon?'#f9e28a':'#ffc96e'):(lemon?'#ffec9d':'#ffd484');c.fill();c.strokeStyle=lemon?'#fff1bd':'#ffe6aa';c.lineWidth=.018;c.stroke();for(let j=0;j<3;j++){const b=a+.19+j*.12;line(c,[[Math.cos(b)*.27,Math.sin(b)*.27],[Math.cos(b)*.52,Math.sin(b)*.52]],lemon?'#fff2bb99':'#ffe5a477',.013);}}ellipse(c,0,0,.1,.1,lemon?'#fff6cf':'#ffebbc');c.restore();}
function interior(c,type){shape(c,type);c.fillStyle=FRUIT_ART.find(f=>f.id===type)?.inside||'#ffe9b8';c.fill();c.save();shape(c,type);c.clip();if(type==='watermelon'){ellipse(c,0,.04,.89,.82,'#e6efbe');ellipse(c,0,.04,.79,.71,'#f89798');ellipse(c,0,.04,.72,.65,grad(c,-.4,-.6,.4,.7,[[0,'#ffb0a6'],[.55,'#f77b83'],[1,'#e85f72']]));seeds(c,[[-.46,-.19,-.5],[-.18,-.43,-.3],[.15,-.39,.2],[.43,-.21,.7],[-.54,.15,-1],[-.24,.18,-.5],[.12,.08,.1],[.47,.17,.8],[-.13,.46,-.2],[.2,.43,.4]],'#734d50',.062);}
 else if(type==='orange'||type==='lemon')segmented(c,type);
 else if(type==='apple'){shape(c,type);c.strokeStyle='#dc7765';c.lineWidth=.13;c.stroke();c.beginPath();c.moveTo(0,-.41);c.bezierCurveTo(-.27,-.06,-.25,.43,0,.64);c.bezierCurveTo(.25,.42,.27,-.07,0,-.41);c.fillStyle='#f7d697';c.fill();seeds(c,[[-.09,.08,-.4],[.1,.16,.4],[-.07,.35,-.2]],'#946544',.075);line(c,[[-.38,-.22],[-.52,.12],[-.41,.39]],'#fff8e5',.05);}
 else if(type==='banana'){shape(c,type);c.strokeStyle='#e9c76b';c.lineWidth=.12;c.stroke();c.beginPath();c.moveTo(-.62,-.48);c.bezierCurveTo(-.52,.49,.08,.91,.68,.18);c.strokeStyle='#e4ca8e';c.lineWidth=.035;c.stroke();seeds(c,[[-.33,.28,-.7],[-.12,.5,-.4],[.13,.53,.2],[.37,.41,.6]],'#c4ad75',.027);}
 else if(type==='strawberry'){shape(c,type);c.strokeStyle='#db6374';c.lineWidth=.15;c.stroke();c.beginPath();c.moveTo(-.42,-.34);c.quadraticCurveTo(0,-.46,.43,-.34);c.quadraticCurveTo(.13,.21,0,.73);c.quadraticCurveTo(-.15,.18,-.42,-.34);c.fillStyle='#fff1ce';c.fill();for(let i=0;i<10;i++){const a=i*TAU/10;line(c,[[Math.sin(a)*.08,.12+Math.cos(a)*.2],[Math.sin(a)*.56,.12+Math.cos(a)*.5]],'#f9d7b2',.018);}}
 else if(type==='pineapple'){shape(c,type);c.strokeStyle='#d29b3e';c.lineWidth=.15;c.stroke();c.fillStyle='#f8d77f';c.fillRect(-.11,-.5,.22,1.5);for(let i=0;i<18;i++){const a=i*2.399,r=.25+((i*7)%9)*.035;line(c,[[Math.cos(a)*r,Math.sin(a)*r+.24],[Math.cos(a)*(r+.16),Math.sin(a)*(r+.16)+.24]],'#f5ce6a',.022);}ellipse(c,0,.24,.08,.55,'#fff0c0');}
 else if(type==='kiwi'){ellipse(c,0,.03,.75,.86,'#8d704e');ellipse(c,0,.03,.65,.76,'#9cbe62');ellipse(c,0,.03,.59,.7,'#b5d978');for(let i=0;i<24;i++){const a=i*TAU/24,x=Math.cos(a),y=Math.sin(a);line(c,[[x*.19,y*.22+.03],[x*.55,y*.65+.03]],i%2?'#d9e7a0':'#99bc59',.018);seeds(c,[[x*.33,y*.41+.03,-a]],'#4d5140',.043);}ellipse(c,0,.03,.15,.24,'#f2edbc');}
 else if(type==='peach'){shape(c,type);c.strokeStyle='#e9977a';c.lineWidth=.15;c.stroke();ellipse(c,0,.18,.26,.35,'#cb8860','#ad7256',.035);for(let i=0;i<7;i++){const x=(i-3)*.055;c.beginPath();c.moveTo(x,-.07);c.quadraticCurveTo(x+.1,.18,x,.43);c.strokeStyle=i%2?'#a76f52':'#e1a47a';c.lineWidth=.026;c.stroke();}c.beginPath();c.ellipse(-.27,-.08,.37,.52,-.5,Math.PI*.7,Math.PI*1.6);c.strokeStyle='#fff0c8';c.lineWidth=.055;c.stroke();}
 else if(type==='coconut'){ellipse(c,0,.07,.79,.82,'#795c47');ellipse(c,0,.07,.67,.7,'#e2cba5');ellipse(c,0,.07,.6,.63,'#fff8e1');ellipse(c,0,.07,.34,.39,grad(c,-.2,-.2,.2,.4,[[0,'#b3c3bd'],[1,'#dae4d6']]));ellipse(c,-.11,-.02,.13,.18,'#f7fcf0');}
 c.restore();shape(c,type);c.strokeStyle=INK;c.lineWidth=.035;c.stroke();}
function rind(c,type){const spec=FRUIT_ART.find(f=>f.id===type)||FRUIT_ART[0];shape(c,type);c.fillStyle=grad(c,-.65,-.7,.7,.85,[[0,type==='peach'?'#ffd6a1':type==='kiwi'?'#c0a27d':type==='coconut'?'#c69a6f':type==='watermelon'?'#7dbb7a':spec.color],[.62,spec.color],[1,type==='watermelon'?'#33775a':type==='banana'?'#dcaf46':type==='orange'?'#dc7a38':type==='apple'?'#d9565c':type==='strawberry'?'#bf465e':type==='pineapple'?'#bb803c':type==='kiwi'?'#856a49':type==='lemon'?'#d2ae3e':type==='peach'?'#e5827c':'#77573f']]);c.fill();c.save();shape(c,type);c.clip();
 if(type==='watermelon'){for(let i=-2;i<=2;i++){c.beginPath();c.moveTo(i*.35-.12,-.9);c.bezierCurveTo(i*.35-.34,-.3,i*.35+.1,.18,i*.35-.04,.9);c.strokeStyle='#327b5e';c.lineWidth=.105;c.stroke();c.beginPath();c.moveTo(i*.35-.03,-.9);c.bezierCurveTo(i*.35-.25,-.2,i*.35+.22,.2,i*.35+.08,.9);c.strokeStyle='#b2d68b88';c.lineWidth=.036;c.stroke();}}
 if(type==='orange'||type==='lemon'){for(let i=0;i<48;i++){const a=i*2.399,r=Math.sqrt((i+.5)/48)*.75;ellipse(c,Math.cos(a)*r,Math.sin(a)*r+.04,.014+(i%3)*.004,.014,i%3?'#fff1b044':'#bd6e2b55');}}
 if(type==='strawberry'){for(let row=0;row<5;row++)for(let col=0;col<5;col++){const x=(col-2)*.27+(row%2)*.1,y=-.33+row*.23;seeds(c,[[x,y,x*.35]],'#ffe0a0',.045);line(c,[[x-.025,y+.04],[x+.005,y+.06]],'#bd5063',.012);}}
 if(type==='pineapple'){for(let i=-5;i<=5;i++){line(c,[[-1,i*.23-1],[1,i*.23+1]],'#a77b42',.026);line(c,[[-1,i*.23+1],[1,i*.23-1]],'#f6d782',.032);}for(let row=0;row<5;row++)for(let col=0;col<4;col++){const x=(col-1.5)*.3+(row%2)*.14,y=-.3+row*.26;line(c,[[x-.04,y+.025],[x,y-.02],[x+.045,y+.025]],'#a7773f',.028);}}
 if(type==='banana'){c.beginPath();c.moveTo(-.7,-.52);c.bezierCurveTo(-.61,.4,-.04,.92,.73,.16);c.strokeStyle='#fff0ae';c.lineWidth=.08;c.stroke();c.beginPath();c.moveTo(-.48,-.37);c.bezierCurveTo(-.31,.26,.19,.62,.67,.26);c.strokeStyle='#b69b4c';c.lineWidth=.026;c.stroke();for(let i=0;i<6;i++)ellipse(c,-.56+i*.2,.47+Math.sin(i)*.15,.014,.023,'#b39145');}
 if(type==='apple'){ellipse(c,-.38,-.18,.15,.31,'#ffb79877');c.beginPath();c.moveTo(.21,-.48);c.quadraticCurveTo(.44,-.07,.2,.58);c.strokeStyle='#c84e5c55';c.lineWidth=.04;c.stroke();for(let i=0;i<20;i++){const a=i*2.4,r=.2+((i*7)%9)*.05;ellipse(c,Math.cos(a)*r,Math.sin(a)*r+.15,.012,.014,'#fff1ba77');}}
 if(type==='peach'){ellipse(c,.42,.18,.38,.53,'#ed7d8570');c.beginPath();c.moveTo(0,-.49);c.bezierCurveTo(.16,-.14,.01,.35,-.02,.76);c.strokeStyle='#c77a6a';c.lineWidth=.034;c.stroke();for(let i=0;i<28;i++){const a=i*2.4,r=Math.sqrt((i+.5)/28)*.7;ellipse(c,Math.cos(a)*r,Math.sin(a)*r+.1,.007,.011,'#fff0c580');}}
 if(type==='kiwi'||type==='coconut'){for(let i=0;i<80;i++){const a=i*2.399,r=Math.sqrt((i+.5)/80)*.9,x=Math.cos(a)*r,y=Math.sin(a)*r;line(c,[[x-.025,y-.055],[x+.015,y+.035]],i%3===0?'#edcf9b99':type==='kiwi'?'#6c583f77':'#684a3977',.012);}if(type==='coconut'){ellipse(c,-.2,-.27,.085,.095,'#624c3d');ellipse(c,.04,-.35,.075,.085,'#624c3d');ellipse(c,.12,-.1,.065,.075,'#624c3d');}}
 // Broad soft highlight gives the fruit volume without covering its texture.
 if(type!=='banana'){c.save();c.translate(-.29,-.31);c.rotate(-.45);ellipse(c,0,0,.09,.23,'#fff6d66b');ellipse(c,.13,-.18,.033,.06,'#ffffff9c');c.restore();}c.restore();shape(c,type);c.strokeStyle=INK;c.lineWidth=.037;c.stroke();
 if(type==='apple'||type==='peach'){line(c,[[0,-.53],[.015,-.78],[.12,-.9]],'#7b6045',.075);leaf(c,.03,-.72,.8,-.1);}
 if(type==='orange'||type==='lemon'){ellipse(c,0,-.73,.11,.045,'#72925d');leaf(c,.03,-.74,.65,-.15);}
 if(type==='watermelon'){line(c,[[.04,-.77],[.1,-.9],[.24,-.88]],'#6e8457',.045);}
 if(type==='banana'){line(c,[[-.72,-.62],[-.63,-.75]],'#795d43',.12);ellipse(c,.83,-.055,.06,.07,'#8d7344');}
 if(type==='strawberry'){for(let i=0;i<5;i++){c.save();c.translate((i-2)*.09,-.58);c.rotate((i-2)*.53);c.beginPath();c.moveTo(0,.07);c.quadraticCurveTo(-.19,-.07,-.14,-.3);c.quadraticCurveTo(.03,-.2,.13,.04);c.fillStyle=i%2?'#72ae78':'#4f9269';c.fill();c.strokeStyle='#47795a';c.lineWidth=.018;c.stroke();c.restore();}line(c,[[0,-.64],[.05,-.92]],'#5a8d63',.055);}
 if(type==='pineapple'){for(let i=-2;i<=2;i++){c.beginPath();c.moveTo(i*.07,-.36);c.quadraticCurveTo(i*.25,-.72,i*.22,-.99+Math.abs(i)*.1);c.quadraticCurveTo(i*.12+.13,-.62,.12+i*.05,-.36);c.fillStyle=i%2?'#78a77a':'#4d8669';c.fill();c.strokeStyle='#47785e';c.lineWidth=.019;c.stroke();}}
}
function halo(c,special,time){if(!special)return;const golden=special==='golden',freeze=special==='freeze',team=special==='team';c.save();c.rotate(Math.sin(time/400)*.1);const color=golden?'#ffe2a0':freeze?'#d0f4f4':team?'#b9d8f4':'#f8d2c6';for(let i=0;i<8;i++){const a=i*TAU/8+time/2600,x=Math.cos(a)*1.03,y=Math.sin(a)*1.03;line(c,[[x*.96,y*.96],[x*1.05,y*1.05]],color,.04);}c.strokeStyle=color;c.lineWidth=.045;c.setLineDash([.13,.1]);c.beginPath();c.arc(0,0,1.015,0,TAU);c.stroke();c.setLineDash([]);c.restore();}
function badge(c,special,time){if(!special)return;const colors={golden:['#ffe8a3','#b48132'],rainbow:['#f3bbd6','#8b6088'],freeze:['#c3eef0','#568d9b'],giant:['#e0efb7','#6f8c56'],storm:['#fff0b3','#ac8839'],team:['#cee4f7','#64899f']},[fill,ink]=colors[special]||colors.rainbow;c.save();c.translate(.5,-.5);ellipse(c,0,0,.23,.23,fill,ink,.025);c.lineCap='round';c.lineJoin='round';if(special==='freeze'){for(let i=0;i<3;i++){c.save();c.rotate(i*Math.PI/3);line(c,[[-.14,0],[.14,0]],ink,.024);line(c,[[.1,-.045],[.06,0],[.1,.045]],ink,.019);line(c,[[-.1,-.045],[-.06,0],[-.1,.045]],ink,.019);c.restore();}}
 else if(special==='storm'){c.beginPath();c.moveTo(.02,-.16);c.lineTo(-.12,.03);c.lineTo(-.01,.03);c.lineTo(-.05,.16);c.lineTo(.14,-.04);c.lineTo(.03,-.04);c.closePath();c.fillStyle=ink;c.fill();}
 else if(special==='team'){ellipse(c,-.07,-.04,.055,.065,'#5f99c0');ellipse(c,.07,-.04,.055,.065,'#df9872');line(c,[[-.12,.1],[-.09,.04],[-.05,.04],[-.02,.1]],'#5f99c0',.04);line(c,[[.02,.1],[.05,.04],[.09,.04],[.12,.1]],'#df9872',.04);}
 else if(special==='rainbow'){for(let i=0;i<4;i++){c.beginPath();c.arc(0,.06,.145-i*.027,Math.PI,TAU);c.strokeStyle=['#d77d8e','#e6b269','#8bb584','#83b9ca'][i];c.lineWidth=.027;c.stroke();}}
 else{c.beginPath();for(let i=0;i<10;i++){const a=-Math.PI/2+i*Math.PI/5,r=i%2?.065:.15;i?c.lineTo(Math.cos(a)*r,Math.sin(a)*r):c.moveTo(Math.cos(a)*r,Math.sin(a)*r);}c.closePath();c.fillStyle=ink;c.fill();}c.restore();}
function bomb(c,time){ellipse(c,0,.12,.73,.72,grad(c,-.6,-.5,.6,.8,[[0,'#667479'],[.5,'#43545a'],[1,'#2e424b']]),'#293e46',.04);c.save();c.rotate(-.32);c.fillStyle='#60757a';c.beginPath();c.roundRect(-.2,-.66,.4,.22,.065);c.fill();c.strokeStyle='#30484f';c.lineWidth=.035;c.stroke();c.beginPath();c.moveTo(0,-.66);c.bezierCurveTo(-.06,-.96,.38,-.75,.33,-1.02);c.strokeStyle='#a79272';c.lineWidth=.055;c.stroke();c.restore();ellipse(c,-.29,-.1,.1,.25,'#b1c1bd66');ellipse(c,.08,.19,.3,.3,'#f8c09c','#e7a17f',.03);line(c,[[-.02,.09],[.19,.29]],'#74584e',.06);line(c,[[.19,.09],[-.02,.29]],'#74584e',.06);for(let i=0;i<5;i++){const a=i*TAU/5+time/700;line(c,[[.6+Math.cos(a)*.07,-.81+Math.sin(a)*.07],[.6+Math.cos(a)*.15,-.81+Math.sin(a)*.15]],i%2?'#f6c567':'#f3a283',.035);}}
export function drawAirFruit(ctx,fruit,{interior:cut=false,side=null,time=0}={}){const r=Number.isFinite(fruit.r)?Math.max(.01,fruit.r):70,type=fruit.type||'apple';ctx.save();ctx.scale(r,r);ctx.lineCap='round';ctx.lineJoin='round';if(side===-1||side===1){ctx.beginPath();ctx.rect(side<0?-1.3:0,-1.3,1.3,2.6);ctx.clip();}if(type==='bomb'){bomb(ctx,time);ctx.restore();return;}const special=fruit.special||(type==='giant'?'giant':null),species=type==='giant'?'watermelon':type;halo(ctx,special,time);if(cut||side!==null){interior(ctx,species);if(side===-1||side===1){ctx.save();shape(ctx,species);ctx.clip();line(ctx,[[0,-1.1],[0,1.1]],'#fff3cb',.038);ctx.restore();}}else{rind(ctx,species);if(special==='golden'){ctx.save();shape(ctx,species);ctx.clip();ctx.globalAlpha=.2;ctx.fillStyle='#ffe7a0';ctx.fillRect(-1,-1,2,2);ctx.restore();}badge(ctx,special,time);if((special==='giant'||special==='team')&&fruit.hp<fruit.maxHp){const damage=Math.max(1,(fruit.maxHp||3)-(fruit.hp||1));ctx.save();shape(ctx,species);ctx.clip();line(ctx,[[-.02,-.62],[.14,-.29],[-.04,-.05],[.15,.19],[.01,.56]],'#f8eac4',.08);line(ctx,[[-.02,-.62],[.14,-.29],[-.04,-.05],[.15,.19],[.01,.56]],'#596a52',.026);if(damage>1){line(ctx,[[.12,-.28],[.43,-.35],[.53,-.12]],'#f8eac4',.06);line(ctx,[[.11,.2],[-.25,.29],[-.4,.56]],'#f8eac4',.06);}ctx.restore();}}ctx.restore();}
export function drawAirBackdrop(ctx,w,h,time=0){ctx.save();ctx.fillStyle=grad(ctx,0,0,w,h,[[0,'#f6f0dc'],[.5,'#e3f0e5'],[1,'#cee5df']]);ctx.fillRect(0,0,w,h);const unit=Math.min(w,h);for(let i=0;i<5;i++){const x=(i*.27-.1)*w+Math.sin(time/4000+i)*unit*.025,y=(i%2?.76:.18)*h;ctx.beginPath();ctx.ellipse(x,y,unit*.28,unit*.1,-.5+i*.35,0,TAU);ctx.fillStyle=['#d9e9d877','#fff7e877','#a8d1c333','#f4c4a433','#b1d9dc44'][i];ctx.fill();}ctx.strokeStyle='#fff9e277';ctx.lineWidth=2;for(let i=0;i<7;i++){ctx.beginPath();ctx.arc(w*(i/6),h+unit*.37,unit*(.55+i*.06),Math.PI*1.08,Math.PI*1.91);ctx.stroke();}for(let i=0;i<18;i++){const x=((i*137.2)%1000)/1000*w,y=((i*83.7)%600)/600*h;ctx.fillStyle=i%2?'#6ca99b30':'#d98f7830';ctx.beginPath();ctx.ellipse(x,y,unit*.004,unit*.009,(i%5)*.7,0,TAU);ctx.fill();}ctx.restore();}
export function drawAirSlash(ctx,points,color='#72d0d4',life=1){if(points.length<2||life<=0)return;ctx.save();ctx.globalAlpha=Math.max(0,Math.min(1,life));ctx.lineJoin='round';ctx.lineCap='round';for(const [width,alpha,paint]of [[18,.12,color],[9,.48,color],[3,1,'#fff8de']]){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.lineWidth=width;ctx.strokeStyle=paint;ctx.globalAlpha=Math.max(0,Math.min(1,life))*alpha;ctx.stroke();}ctx.restore();}
